begin;set local search_path=public,extensions;select plan(14);
select ok((select count(*)=3 and bool_and(p.prosecdef and p.proconfig::text like '%search_path=pg_catalog%')from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname in('add_catalog_questionnaire_section','add_catalog_questionnaire_question','add_catalog_questionnaire_rule')),'composition RPCs are security definer with fixed paths');
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname in('add_catalog_questionnaire_section','add_catalog_questionnaire_question','add_catalog_questionnaire_rule')and(has_function_privilege('anon',p.oid,'EXECUTE')or has_function_privilege('service_role',p.oid,'EXECUTE'))),'non-user roles cannot compose snapshots');
select ok((select count(*)=3 and bool_and(has_function_privilege('authenticated',p.oid,'EXECUTE'))from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname in('add_catalog_questionnaire_section','add_catalog_questionnaire_question','add_catalog_questionnaire_rule')),'authenticated receives explicit composition execution');
select ok(not has_table_privilege('authenticated','public.questionnaire_version_questions','INSERT')and not has_table_privilege('authenticated','public.questionnaire_version_rules','INSERT'),'direct snapshot link writes remain denied');

insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)values
('fb100000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','p06-composition-admin@example.invalid','',now(),'{}','{}',now(),now()),
('fb100000-0000-0000-0000-000000000002','00000000-0000-0000-0000-000000000000','authenticated','authenticated','p06-composition-outsider@example.invalid','',now(),'{}','{}',now(),now());
insert into public.platform_user_roles(user_id,role_code)values('fb100000-0000-0000-0000-000000000001','MATRICIA_ADMIN');
insert into public.organizations(id,legal_name,display_name,status,created_by)values('fb110000-0000-0000-0000-000000000001','P06 Composition Steward','P06 Composition Steward','ACTIVE','fb100000-0000-0000-0000-000000000001');
insert into public.catalog_libraries(id,code,slug,steward_organization_id,status,created_by)values('fb120000-0000-0000-0000-000000000001','P06_COMPOSE','p06-compose','fb110000-0000-0000-0000-000000000001','DRAFT','fb100000-0000-0000-0000-000000000001');
insert into public.catalog_releases(id,library_id,release_key,status,source_bundle_hash,created_by)values('fb130000-0000-0000-0000-000000000001','fb120000-0000-0000-0000-000000000001','P06.COMPOSE.V1','DRAFT',repeat('b',64),'fb100000-0000-0000-0000-000000000001');
insert into public.question_bank_questions(id,library_id,question_key,scope,created_by)values('fb140000-0000-0000-0000-000000000001','fb120000-0000-0000-0000-000000000001','P06_APPROVED','LIBRARY','fb100000-0000-0000-0000-000000000001');
insert into public.question_versions(id,question_id,library_id,version,status,label_fr,label_ar,answer_type,data_key,content_hash,change_reason,created_by)values('fb141000-0000-0000-0000-000000000001','fb140000-0000-0000-0000-000000000001','fb120000-0000-0000-0000-000000000001',1,'APPROVED','Question approuvée','سؤال معتمد','YES_NO','p06.approved',repeat('c',64),'Version approuvée','fb100000-0000-0000-0000-000000000001');
insert into public.question_rules(id,library_id,rule_key,created_by)values('fb150000-0000-0000-0000-000000000001','fb120000-0000-0000-0000-000000000001','P06_APPROVED_RULE','fb100000-0000-0000-0000-000000000001'),('fb150000-0000-0000-0000-000000000002','fb120000-0000-0000-0000-000000000001','P06_SENSITIVE_RULE','fb100000-0000-0000-0000-000000000001');
insert into public.question_rule_versions(id,rule_id,library_id,version,status,condition_ast,actions,dependency_graph,priority,sensitive,compiled_hash,change_reason,created_by)values
('fb151000-0000-0000-0000-000000000001','fb150000-0000-0000-0000-000000000001','fb120000-0000-0000-0000-000000000001',1,'APPROVED','{"kind":"TRUE"}','[{"type":"NOOP"}]','{}',10,false,repeat('d',64),'Version approuvée','fb100000-0000-0000-0000-000000000001'),
('fb151000-0000-0000-0000-000000000002','fb150000-0000-0000-0000-000000000002','fb120000-0000-0000-0000-000000000001',1,'APPROVED','{"kind":"TRUE"}','[{"type":"NOOP"}]','{}',20,true,repeat('e',64),'Version sensible','fb100000-0000-0000-0000-000000000001');
create temporary table p06_compose_observed(key text primary key,value jsonb);grant select,insert on p06_compose_observed to authenticated;grant usage on schema extensions to authenticated;

set local role authenticated;select set_config('request.jwt.claims','{"sub":"fb100000-0000-0000-0000-000000000001","role":"authenticated","aal":"aal2"}',true);
insert into p06_compose_observed values('created',public.create_catalog_questionnaire('fb120000-0000-0000-0000-000000000001','fb130000-0000-0000-0000-000000000001','COMPOSE','{"title_fr":"Diagnostic composé","title_ar":"تشخيص مركب","description_fr":"Questionnaire de composition","description_ar":"استبيان التكوين","audience":"CLIENT","engine_version":"1.0.0","policy_version":"P06-2","sensitive":false,"section_key":"GENERAL","section_label_fr":"Général","section_label_ar":"عام"}','Création composition','compose-create'));
insert into p06_compose_observed values('section',public.add_catalog_questionnaire_section((select(value->>'version_id')::uuid from p06_compose_observed where key='created'),'{"section_key":"DETAILS","label_fr":"Détails","label_ar":"تفاصيل"}'::jsonb,1,'compose-section'));
insert into p06_compose_observed values('question',public.add_catalog_questionnaire_question((select(value->>'version_id')::uuid from p06_compose_observed where key='created'),(select(value->>'section_id')::uuid from p06_compose_observed where key='section'),'fb141000-0000-0000-0000-000000000001',10,true,2,'compose-question'));
insert into p06_compose_observed values('rule',public.add_catalog_questionnaire_rule((select(value->>'version_id')::uuid from p06_compose_observed where key='created'),'fb151000-0000-0000-0000-000000000001',20,3,'compose-rule'));
insert into p06_compose_observed values('rule-replay',public.add_catalog_questionnaire_rule((select(value->>'version_id')::uuid from p06_compose_observed where key='created'),'fb151000-0000-0000-0000-000000000001',20,3,'compose-rule','fb160000-0000-0000-0000-000000000099'));
reset role;
select is((select value->>'sort_order'from p06_compose_observed where key='section'),'2','next section receives the next stable order');
select ok((select section_key='DETAILS'and label_ar='تفاصيل'and content_hash~'^[0-9a-f]{64}$'from public.questionnaire_sections where id=(select(value->>'section_id')::uuid from p06_compose_observed where key='section')),'bilingual immutable section is materialized');
select ok((select sort_order=10 and required_override from public.questionnaire_version_questions where question_version_id='fb141000-0000-0000-0000-000000000001'),'approved question version is linked in the selected section and order');
select ok((select evaluation_order=20 from public.questionnaire_version_rules where rule_version_id='fb151000-0000-0000-0000-000000000001'),'approved rule version is linked at its evaluation order');
select is((select value from p06_compose_observed where key='rule'),(select value from p06_compose_observed where key='rule-replay'),'retry returns the durable response without a duplicate link');
select ok((select row_version=4 and snapshot_hash=(select value->>'snapshot_hash'from p06_compose_observed where key='rule')from public.questionnaire_versions where id=(select(value->>'version_id')::uuid from p06_compose_observed where key='created')),'each composition advances optimistic version and canonical snapshot hash');
select ok((select count(*)=3 from public.audit_events where action in('catalog.questionnaire.section_added','catalog.questionnaire.question_added','catalog.questionnaire.rule_added')and resource_id=(select value->>'questionnaire_id'from p06_compose_observed where key='created'))and(select count(*)=3 from public.event_outbox where event_type in('CatalogQuestionnaireSectionAddedV1','CatalogQuestionnaireQuestionAddedV1','CatalogQuestionnaireRuleAddedV1')and aggregate_id=(select value->>'questionnaire_id'from p06_compose_observed where key='created')),'each mutation emits exactly one audit and one Outbox event');
set local role authenticated;select set_config('request.jwt.claims','{"sub":"fb100000-0000-0000-0000-000000000001","role":"authenticated","aal":"aal2"}',true);
select throws_ok(format('select public.add_catalog_questionnaire_section(%L,%L::jsonb,3,%L)',(select value->>'version_id'from p06_compose_observed where key='created'),'{"section_key":"STALE","label_fr":"Obsolète","label_ar":"قديم"}','compose-stale'),'40001'::char(5),'STALE_CATALOG_VERSION','stale composition loses optimistic concurrency race');
select set_config('request.jwt.claims','{"sub":"fb100000-0000-0000-0000-000000000001","role":"authenticated","aal":"aal1"}',true);
select throws_ok(format('select public.add_catalog_questionnaire_rule(%L,%L,30,4,%L)',(select value->>'version_id'from p06_compose_observed where key='created'),'fb151000-0000-0000-0000-000000000002','compose-sensitive'),'42501'::char(5),'CATALOG_SENSITIVE_MFA_REQUIRED','sensitive rule composition requires AAL2');
select set_config('request.jwt.claims','{"sub":"fb100000-0000-0000-0000-000000000002","role":"authenticated","aal":"aal2"}',true);
select throws_ok(format('select public.add_catalog_questionnaire_section(%L,%L::jsonb,4,%L)',(select value->>'version_id'from p06_compose_observed where key='created'),'{"section_key":"HIDDEN","label_fr":"Caché","label_ar":"مخفي"}','compose-hidden'),'42501'::char(5),'CATALOG_SCOPE_DENIED','outsider cannot infer or mutate snapshot content');
reset role;select * from finish();rollback;
